{
  "predictors": [
    {
      "name": "Dividend Coverage Volatility",
      "construction": "Standard deviation of the ratio of Earnings Before Interest and Taxes (EBIT) to dividends paid over the past 5 years",
      "rationale": "Firms with high dividend coverage volatility may face more uncertainty in their ability to maintain dividends, which could lead investors to require a higher return",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Inventory Turnover Growth",
      "construction": "Rate of change in the ratio of cost of goods sold to inventory over the past 1 year",
      "rationale": "Firms improving their efficiency in selling their inventory are likely to have improving profitability and thus higher future returns",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Debt Maturity Structure",
      "construction": "Ratio of long-term debt to total debt",
      "rationale": "Firms with more long-term debt in their debt structure may be considered less risky by investors, leading to higher future returns",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Management Tenure Dispersion",
      "construction": "Standard deviation of the tenure of the top 5 executives",
      "rationale": "Firms with a wider range of executive experience levels may benefit from diverse perspectives and innovative thinking, leading to higher future returns",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "R&D Expenditure Stability",
      "construction": "Standard deviation of the ratio of Research and Development (R&D) expenditure to total assets over the past 5 years",
      "rationale": "Firms with stable R&D expenditure may be more likely to generate steady flow of innovations, leading to higher future returns",
      "higher_returns_for": "Low values of the measure"
    },
    {
      "name": "Working Capital Efficiency",
      "construction": "Ratio of current assets excluding cash to current liabilities",
      "rationale": "Firms that manage their working capital efficiently may be more profitable and generate higher future returns",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Relative Marketing Expenses",
      "construction": "Ratio of marketing expenses to total sales",
      "rationale": "Firms that spend more on marketing relative to their sales may be investing in their future growth, leading to higher future returns",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Employee Productivity Growth",
      "construction": "Rate of change in the ratio of sales to number of employees over the past 1 year",
      "rationale": "Firms improving their employee productivity are likely to be more profitable and thus have higher future returns",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Foreign Sales Ratio",
      "construction": "Ratio of foreign sales to total sales",
      "rationale": "Firms with higher proportion of foreign sales may have more diversified revenue streams, reducing risk and increasing expected returns",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Pension Funding Status",
      "construction": "Ratio of pension assets to projected pension obligations",
      "rationale": "Firms with better-funded pension plans may face less risk from future pension obligations, leading to higher future returns",
      "higher_returns_for": "High values of the measure"
    }
  ]
}
